from datetime import date

# 인사 퇴직 목록과 계정 잠금 기록을 맞대어 '지체 없이' 회수됐는지 본다(가상 값)
leavers = {"kim": date(2026, 9, 1), "lee": date(2026, 9, 10), "park": date(2026, 9, 20)}
disabled = {"kim": date(2026, 9, 1), "lee": date(2026, 9, 17)}  # park 은 아직 살아 있다

for user, left in leavers.items():
    off = disabled.get(user)
    if off is None:
        print(user, "예외: 계정이 아직 살아 있다")
    elif (off - left).days > 1:
        print(user, f"예외: 퇴직 {(off - left).days}일 뒤 회수")
    else:
        print(user, "양호")

# 배포 기록과 변경 승인 티켓을 맞대어 본다(가상 값)
deploys = [
    {"id": "D1", "ticket": "CHG-101", "by": "dev1"},
    {"id": "D2", "ticket": None,      "by": "dev2"},
    {"id": "D3", "ticket": "CHG-103", "by": "dev3"},
]
tickets = {
    "CHG-101": {"requester": "dev1", "approver": "lead1"},
    "CHG-103": {"requester": "dev3", "approver": "dev3"},
}

for d in deploys:
    t = tickets.get(d["ticket"])
    if t is None:
        print(d["id"], "예외: 승인 기록 없는 배포")
    elif t["approver"] == t["requester"]:
        print(d["id"], "예외: 요청자가 스스로 승인(직무분리 위반)")
    else:
        print(d["id"], "양호")
